-- 00005_pregnancy_v2.sql — pregnancy mode v2 (M7, T-M7-01, docs/pregnancy-v2/README.md § Data):
-- admin-defined week details and care plan, the per-day extras pregnancy_symptom_logs lacks, and the
-- user's per-week bookmark / task state. v1 tables (pregnancy_weekly_content, pregnancy_symptom_logs, …)
-- and the /api/v1/pregnancy/* contract are untouched; the new tables serve /api/v1/pregnancy/v2/*
-- (Go only, D-20).
--
-- Twin of backend/database/migrations/2026_09_26_000001_create_pregnancy_v2_tables.php
-- (Laravel owns the prod schema until T-M2-27); `make schema-diff` proves both build the same tables
-- and seed the same number of rows. Spelled the way mariadb-dump prints the Laravel-built tables (JSON
-- columns written as `json`, see migrations.md). IF NOT EXISTS + INSERT IGNORE (unique week_number,
-- key, and message_contents (group, item_key, locale)): a database whose Laravel half already created
-- and seeded them (prod at cutover, T-M2-27: baseline stamped, then migrations after 00001 applied)
-- must not fail or duplicate rows here, and admin edits are never overwritten.
--
-- Seeds (generated from one source together with the Laravel twin; Tehran wall-clock timestamps like
-- the baseline's `languages` seed):
--   * pregnancy_week_details weeks 1–42 — v1 pregnancy_weekly_content text where it exists, the Week
--     artboard copy for week 8, placeholder copy for the rest; every row carries a `[needs review]`
--     source entry and reviewed_at NULL.
--   * pregnancy_care_items — the 5 items of the Calendar artboard.
--   * message_contents groups pregnancy_week_tip (1–42), pregnancy_alert (one row per T-M7-04 rule with
--     default params + texts, plus `legend`) and pregnancy_setup, fa + en.
-- ALL seeded medical copy, windows and thresholds need a clinician's sign-off before production (T-M7-15).

-- +goose Up
CREATE TABLE IF NOT EXISTS `pregnancy_week_details` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `week_number` tinyint(3) unsigned NOT NULL,
  `size_label` json DEFAULT NULL,
  `illustration_key` varchar(40) DEFAULT NULL,
  `length_cm` varchar(20) DEFAULT NULL,
  `weight_g` varchar(20) DEFAULT NULL,
  `heart_rate` varchar(20) DEFAULT NULL,
  `headline` json DEFAULT NULL,
  `highlights` json DEFAULT NULL,
  `body_symptoms` json DEFAULT NULL,
  `body_text` json DEFAULT NULL,
  `tasks` json DEFAULT NULL,
  `warning` json DEFAULT NULL,
  `reviewer_name` json DEFAULT NULL,
  `reviewed_at` date DEFAULT NULL,
  `sources` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pregnancy_week_details_week_number_unique` (`week_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `pregnancy_care_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `key` varchar(64) NOT NULL,
  `title` json NOT NULL,
  `prep` json DEFAULT NULL,
  `kind` varchar(10) NOT NULL,
  `week_from` tinyint(3) unsigned NOT NULL,
  `week_to` tinyint(3) unsigned NOT NULL,
  `remind_before` smallint(5) unsigned NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pregnancy_care_items_key_unique` (`key`),
  KEY `pregnancy_care_items_is_active_sort_order_index` (`is_active`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `pregnancy_daily_extras` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `log_date` date NOT NULL,
  `mood` tinyint(3) unsigned DEFAULT NULL,
  `water_glasses` tinyint(3) unsigned DEFAULT NULL,
  `heartburn_severity` varchar(10) DEFAULT NULL,
  `constipation_severity` varchar(10) DEFAULT NULL,
  `visit_note` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pregnancy_daily_extras_user_id_log_date_unique` (`user_id`,`log_date`),
  CONSTRAINT `pregnancy_daily_extras_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `pregnancy_week_user_state` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `week` tinyint(3) unsigned NOT NULL,
  `bookmarked` tinyint(1) NOT NULL DEFAULT 0,
  `done_task_keys` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pregnancy_week_user_state_user_id_week_unique` (`user_id`,`week`),
  CONSTRAINT `pregnancy_week_user_state_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




-- +goose Down
-- Removes only the seeded rows nobody touched (T-M2-34, review #14): the seed is fa/en with label
-- "<group> / <item_key>" and created_at = updated_at; every admin edit bumps updated_at and admin-added
-- rows in other locales are kept, so a rollback never loses curated copy. Re-running Up re-seeds the
-- defaults with INSERT IGNORE and leaves the kept rows alone.
DELETE FROM `message_contents`
 WHERE `group` IN ('pregnancy_week_tip', 'pregnancy_alert', 'pregnancy_setup')
   AND `locale` IN ('fa', 'en')
   AND `label` = CONCAT(`group`, ' / ', `item_key`)
   AND `updated_at` <=> `created_at`;
DROP TABLE IF EXISTS `pregnancy_week_user_state`;
DROP TABLE IF EXISTS `pregnancy_daily_extras`;
DROP TABLE IF EXISTS `pregnancy_care_items`;
DROP TABLE IF EXISTS `pregnancy_week_details`;
